insert into menu_items(menu_key,title,path,sort_order,permission,children,is_active,parent_id,updated_at)
select menu_key,title,path,sort_order,null,'[]'::jsonb,true,null,now()
from _central_menu_097
on conflict(menu_key) where menu_key is not null do update set
  title=excluded.title,
  path=excluded.path,
  sort_order=excluded.sort_order,
  children='[]'::jsonb,
  parent_id=null,
  is_active=true,
  updated_at=now();

do $$
declare
  r record;
  child text;
  root_id menu_items.id%type;
  child_id menu_items.id%type;
  n integer;
begin
  for r in select * from _central_menu_097 order by sort_order loop
    select id into root_id from menu_items where menu_key=r.menu_key;
    n:=0;

    for child in select jsonb_array_elements_text(r.children) loop
      n:=n+1;
      insert into menu_items(
        menu_key,title,path,sort_order,permission,children,is_active,parent_id,updated_at
      )
      values(
        r.menu_key||':child:'||lpad(n::text,3,'0'),
        child,
        r.path||'&tab='||n,
        n,
        null,
        '[]'::jsonb,
        true,
        root_id,
        now()
      )
      on conflict(menu_key) where menu_key is not null do update set
        title=excluded.title,
        path=excluded.path,
        sort_order=excluded.sort_order,
        parent_id=excluded.parent_id,
        is_active=true,
        updated_at=now()
      returning id into child_id;

      insert into menu_item_panels(menu_item_id,panel_code,is_shared,sort_order,is_visible)
      select child_id,'admin',true,n,true
      where not exists (
        select 1 from menu_item_panels
        where menu_item_id=child_id and panel_code='admin'
      );

      update menu_item_panels
      set is_shared=true, sort_order=n, is_visible=true
      where menu_item_id=child_id and panel_code='admin';
    end loop;

    insert into menu_item_panels(menu_item_id,panel_code,is_shared,sort_order,is_visible)
    select root_id,'admin',true,r.sort_order,true
    where not exists (
      select 1 from menu_item_panels
      where menu_item_id=root_id and panel_code='admin'
    );

    update menu_item_panels
    set is_shared=true, sort_order=r.sort_order, is_visible=true
    where menu_item_id=root_id and panel_code='admin';
  end loop;
end $$;

commit;
